// R_TRIG / F_TRIG function blocks and manual edge detection pattern
VAR
    rTrig : R_TRIG;
    prevSignal : BOOL;
    rising : BOOL;
END_VAR
rTrig(CLK := rawSignal); // rTrig.Q is TRUE for one scan on rising edge
// Manual edge pattern:
rising := rawSignal AND NOT prevSignal;
prevSignal := rawSignal;

// Standard IEC TON timer: MUST invoke unconditionally OUTSIDE CASE/IF every scan!
VAR
    timer : TON;
    runTimer : BOOL;
END_VAR
// Control via boolean IN flag (never put timer(...) only inside an IF/CASE arm):
runTimer := (state = 1) AND NOT resetCmd;
timer(IN := runTimer, PT := T#2s);
IF timer.Q THEN
    // Timer expired; timer.ET holds elapsed time
END_IF;
